// Karma configuration file, see link for more information
// https://karma-runner.github.io/1.0/config/configuration-file.html

module.exports = function (config) {
  config.set({
    basePath: '',
    frameworks: ['jasmine', '@angular/build'],
    plugins: [
      require('karma-jasmine'),
      require('karma-brave-launcher'),
      require('karma-jasmine-html-reporter'),
      require('karma-coverage')
    ],
    client: {
      jasmine: {
        // you can add configuration options for Jasmine here
        // the possible options are listed at https://jasmine.github.io/api/edge/Configuration.html
        // for example, you can disable the random execution with `random: false`
        // or set a specific seed with `seed: 4321`
      },
      clearContext: false // leave Jasmine Spec Runner output visible in browser
    },
    jasmineHtmlReporter: {
      suppressAll: true // removes the duplicated traces
    },
    coverageReporter: {
      dir: require('path').join(__dirname, './coverage/release-planner-web'),
      subdir: '.',
      reporters: [
        { type: 'html' },
        { type: 'text-summary' }
      ]
    },
    reporters: ['progress', 'kjhtml'],
    browsers: ['Brave'],
    restartOnFileChange: true,
    customLaunchers: {
      Brave: {
        base: 'BraveBrowser',
        flags: ['--no-sandbox', '--disable-gpu']
      }
    }
  });
};

/* You can add global styles to this file, and also import other style files */
@import "tailwindcss";

/* ============================================
   CSS VARIABLES - Design System Foundation
   ============================================ */

@layer theme {
  :root {
    /* ==================== Colors ==================== */

    /* Primary Colors */
    --color-primary-50: #f0f9ff;
    --color-primary-100: #e0f2fe;
    --color-primary-200: #bae6fd;
    --color-primary-300: #7dd3fc;
    --color-primary-400: #38bdf8;
    --color-primary-500: #0ea5e9;
    --color-primary-600: #0284c7;
    --color-primary-700: #0369a1;
    --color-primary-800: #075985;
    --color-primary-900: #0c4a6e;
    --color-primary-950: #082f49;

    /* Secondary Colors */
    --color-secondary-50: #faf5ff;
    --color-secondary-100: #f3e8ff;
    --color-secondary-200: #e9d5ff;
    --color-secondary-300: #d8b4fe;
    --color-secondary-400: #c084fc;
    --color-secondary-500: #a855f7;
    --color-secondary-600: #9333ea;
    --color-secondary-700: #7e22ce;
    --color-secondary-800: #6b21a8;
    --color-secondary-900: #581c87;
    --color-secondary-950: #3b0764;

    /* Accent Colors */
    --color-accent-50: #fef3c7;
    --color-accent-100: #fde68a;
    --color-accent-200: #fcd34d;
    --color-accent-300: #fbbf24;
    --color-accent-400: #f59e0b;
    --color-accent-500: #d97706;
    --color-accent-600: #b45309;
    --color-accent-700: #92400e;
    --color-accent-800: #78350f;
    --color-accent-900: #451a03;

    /* Neutral/Gray Colors */
    --color-neutral-50: #fafaf9;
    --color-neutral-100: #f5f5f4;
    --color-neutral-200: #e7e5e4;
    --color-neutral-300: #d6d3d1;
    --color-neutral-400: #a8a29e;
    --color-neutral-500: #78716c;
    --color-neutral-600: #57534e;
    --color-neutral-700: #44403c;
    --color-neutral-800: #292524;
    --color-neutral-900: #1c1917;
    --color-neutral-950: #0c0a09;

    /* Semantic Colors */
    --color-success-50: #f0fdf4;
    --color-success-100: #dcfce7;
    --color-success-500: #22c55e;
    --color-success-600: #16a34a;
    --color-success-700: #15803d;

    --color-warning-50: #fffbeb;
    --color-warning-100: #fef3c7;
    --color-warning-500: #f59e0b;
    --color-warning-600: #d97706;
    --color-warning-700: #b45309;

    --color-error-50: #fef2f2;
    --color-error-100: #fee2e2;
    --color-error-500: #ef4444;
    --color-error-600: #dc2626;
    --color-error-700: #b91c1c;

    --color-info-50: #eff6ff;
    --color-info-100: #dbeafe;
    --color-info-500: #3b82f6;
    --color-info-600: #2563eb;
    --color-info-700: #1d4ed8;

    /* Background & Surface Colors */
    --color-background: #ffffff;
    --color-background-alt: #fafaf9;
    --color-surface: #ffffff;
    --color-surface-elevated: #f5f5f4;

    /* Text Colors */
    --color-text-primary: #1c1917;
    --color-text-secondary: #57534e;
    --color-text-tertiary: #78716c;
    --color-text-inverse: #ffffff;

    /* Border Colors */
    --color-border-light: #e7e5e4;
    --color-border-base: #d6d3d1;
    --color-border-dark: #a8a29e;

    /* ==================== Typography ==================== */

    /* Font Families */
    --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    --font-serif: 'Georgia', 'Times New Roman', serif;
    --font-mono: 'JetBrains Mono', 'Fira Code', 'Courier New', monospace;
    --font-display: 'Inter', sans-serif;

    /* Font Sizes */
    --font-size-xs: 0.75rem;      /* 12px */
    --font-size-sm: 0.875rem;     /* 14px */
    --font-size-base: 1rem;       /* 16px */
    --font-size-lg: 1.125rem;     /* 18px */
    --font-size-xl: 1.25rem;      /* 20px */
    --font-size-2xl: 1.5rem;      /* 24px */
    --font-size-3xl: 1.875rem;    /* 30px */
    --font-size-4xl: 2.25rem;     /* 36px */
    --font-size-5xl: 3rem;        /* 48px */
    --font-size-6xl: 3.75rem;     /* 60px */
    --font-size-7xl: 4.5rem;      /* 72px */

    /* Font Weights */
    --font-weight-thin: 100;
    --font-weight-extralight: 200;
    --font-weight-light: 300;
    --font-weight-normal: 400;
    --font-weight-medium: 500;
    --font-weight-semibold: 600;
    --font-weight-bold: 700;
    --font-weight-extrabold: 800;
    --font-weight-black: 900;

    /* Line Heights */
    --line-height-none: 1;
    --line-height-tight: 1.25;
    --line-height-snug: 1.375;
    --line-height-normal: 1.5;
    --line-height-relaxed: 1.625;
    --line-height-loose: 2;

    /* Letter Spacing */
    --letter-spacing-tighter: -0.05em;
    --letter-spacing-tight: -0.025em;
    --letter-spacing-normal: 0em;
    --letter-spacing-wide: 0.025em;
    --letter-spacing-wider: 0.05em;
    --letter-spacing-widest: 0.1em;

    /* ==================== Spacing ==================== */

    --spacing-0: 0;
    --spacing-px: 1px;
    --spacing-0-5: 0.125rem;   /* 2px */
    --spacing-1: 0.25rem;      /* 4px */
    --spacing-1-5: 0.375rem;   /* 6px */
    --spacing-2: 0.5rem;       /* 8px */
    --spacing-2-5: 0.625rem;   /* 10px */
    --spacing-3: 0.75rem;      /* 12px */
    --spacing-3-5: 0.875rem;   /* 14px */
    --spacing-4: 1rem;         /* 16px */
    --spacing-5: 1.25rem;      /* 20px */
    --spacing-6: 1.5rem;       /* 24px */
    --spacing-7: 1.75rem;      /* 28px */
    --spacing-8: 2rem;         /* 32px */
    --spacing-9: 2.25rem;      /* 36px */
    --spacing-10: 2.5rem;      /* 40px */
    --spacing-11: 2.75rem;     /* 44px */
    --spacing-12: 3rem;        /* 48px */
    --spacing-14: 3.5rem;      /* 56px */
    --spacing-16: 4rem;        /* 64px */
    --spacing-20: 5rem;        /* 80px */
    --spacing-24: 6rem;        /* 96px */
    --spacing-28: 7rem;        /* 112px */
    --spacing-32: 8rem;        /* 128px */
    --spacing-36: 9rem;        /* 144px */
    --spacing-40: 10rem;       /* 160px */
    --spacing-44: 11rem;       /* 176px */
    --spacing-48: 12rem;       /* 192px */
    --spacing-52: 13rem;       /* 208px */
    --spacing-56: 14rem;       /* 224px */
    --spacing-60: 15rem;       /* 240px */
    --spacing-64: 16rem;       /* 256px */
    --spacing-72: 18rem;       /* 288px */
    --spacing-80: 20rem;       /* 320px */
    --spacing-96: 24rem;       /* 384px */

    /* ==================== Border Radius ==================== */

    --radius-none: 0;
    --radius-sm: 0.125rem;     /* 2px */
    --radius-base: 0.25rem;    /* 4px */
    --radius-md: 0.375rem;     /* 6px */
    --radius-lg: 0.5rem;       /* 8px */
    --radius-xl: 0.75rem;      /* 12px */
    --radius-2xl: 1rem;        /* 16px */
    --radius-3xl: 1.5rem;      /* 24px */
    --radius-full: 9999px;

    /* ==================== Shadows ==================== */

    --shadow-xs: 0 1px 2px 0 rgb(0 0 0 / 0.05);
    --shadow-sm: 0 1px 3px 0 rgb(0 0 0 / 0.1), 0 1px 2px -1px rgb(0 0 0 / 0.1);
    --shadow-base: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
    --shadow-md: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);
    --shadow-lg: 0 20px 25px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1);
    --shadow-xl: 0 25px 50px -12px rgb(0 0 0 / 0.25);
    --shadow-2xl: 0 50px 100px -20px rgb(0 0 0 / 0.25);
    --shadow-inner: inset 0 2px 4px 0 rgb(0 0 0 / 0.05);
    --shadow-none: 0 0 #0000;

    /* ==================== Z-Index ==================== */

    --z-index-dropdown: 1000;
    --z-index-sticky: 1020;
    --z-index-fixed: 1030;
    --z-index-modal-backdrop: 1040;
    --z-index-modal: 1050;
    --z-index-popover: 1060;
    --z-index-tooltip: 1070;

    /* ==================== Transitions ==================== */

    --transition-fast: 150ms cubic-bezier(0.4, 0, 0.2, 1);
    --transition-base: 200ms cubic-bezier(0.4, 0, 0.2, 1);
    --transition-slow: 300ms cubic-bezier(0.4, 0, 0.2, 1);
    --transition-slower: 500ms cubic-bezier(0.4, 0, 0.2, 1);

    /* ==================== Breakpoints (for reference) ==================== */

    --breakpoint-sm: 640px;
    --breakpoint-md: 768px;
    --breakpoint-lg: 1024px;
    --breakpoint-xl: 1280px;
    --breakpoint-2xl: 1536px;

    /* ==================== Container Max Widths ==================== */

    --container-sm: 640px;
    --container-md: 768px;
    --container-lg: 1024px;
    --container-xl: 1280px;
    --container-2xl: 1536px;
  }

  /* Dark Mode Variables */
  @media (prefers-color-scheme: dark) {
    :root {
      --color-background: #0c0a09;
      --color-background-alt: #1c1917;
      --color-surface: #1c1917;
      --color-surface-elevated: #292524;

      --color-text-primary: #fafaf9;
      --color-text-secondary: #d6d3d1;
      --color-text-tertiary: #a8a29e;
      --color-text-inverse: #1c1917;

      --color-border-light: #292524;
      --color-border-base: #44403c;
      --color-border-dark: #57534e;
    }
  }
}

/* ============================================
   Tailwind Theme Configuration
   ============================================ */

@theme {
  /* Primary Colors */
  --color-primary-50: var(--color-primary-50);
  --color-primary-100: var(--color-primary-100);
  --color-primary-200: var(--color-primary-200);
  --color-primary-300: var(--color-primary-300);
  --color-primary-400: var(--color-primary-400);
  --color-primary-500: var(--color-primary-500);
  --color-primary-600: var(--color-primary-600);
  --color-primary-700: var(--color-primary-700);
  --color-primary-800: var(--color-primary-800);
  --color-primary-900: var(--color-primary-900);
  --color-primary-950: var(--color-primary-950);

  /* Secondary Colors */
  --color-secondary-50: var(--color-secondary-50);
  --color-secondary-100: var(--color-secondary-100);
  --color-secondary-200: var(--color-secondary-200);
  --color-secondary-300: var(--color-secondary-300);
  --color-secondary-400: var(--color-secondary-400);
  --color-secondary-500: var(--color-secondary-500);
  --color-secondary-600: var(--color-secondary-600);
  --color-secondary-700: var(--color-secondary-700);
  --color-secondary-800: var(--color-secondary-800);
  --color-secondary-900: var(--color-secondary-900);
  --color-secondary-950: var(--color-secondary-950);

  /* Accent Colors */
  --color-accent-50: var(--color-accent-50);
  --color-accent-100: var(--color-accent-100);
  --color-accent-200: var(--color-accent-200);
  --color-accent-300: var(--color-accent-300);
  --color-accent-400: var(--color-accent-400);
  --color-accent-500: var(--color-accent-500);
  --color-accent-600: var(--color-accent-600);
  --color-accent-700: var(--color-accent-700);
  --color-accent-800: var(--color-accent-800);
  --color-accent-900: var(--color-accent-900);

  /* Neutral Colors */
  --color-neutral-50: var(--color-neutral-50);
  --color-neutral-100: var(--color-neutral-100);
  --color-neutral-200: var(--color-neutral-200);
  --color-neutral-300: var(--color-neutral-300);
  --color-neutral-400: var(--color-neutral-400);
  --color-neutral-500: var(--color-neutral-500);
  --color-neutral-600: var(--color-neutral-600);
  --color-neutral-700: var(--color-neutral-700);
  --color-neutral-800: var(--color-neutral-800);
  --color-neutral-900: var(--color-neutral-900);
  --color-neutral-950: var(--color-neutral-950);

  /* Success Colors */
  --color-success-50: var(--color-success-50);
  --color-success-100: var(--color-success-100);
  --color-success-500: var(--color-success-500);
  --color-success-600: var(--color-success-600);
  --color-success-700: var(--color-success-700);
  --color-success-200: #bbf7d0;
  --color-success-800: #166534;
  --color-success-900: #14532d;

  /* Warning Colors */
  --color-warning-50: var(--color-warning-50);
  --color-warning-100: var(--color-warning-100);
  --color-warning-500: var(--color-warning-500);
  --color-warning-600: var(--color-warning-600);
  --color-warning-700: var(--color-warning-700);
  --color-warning-200: #fde68a;
  --color-warning-800: #92400e;
  --color-warning-900: #78350f;

  /* Error Colors */
  --color-error-50: var(--color-error-50);
  --color-error-100: var(--color-error-100);
  --color-error-500: var(--color-error-500);
  --color-error-600: var(--color-error-600);
  --color-error-700: var(--color-error-700);
  --color-error-200: #fecaca;
  --color-error-800: #991b1b;
  --color-error-900: #7f1d1d;

  /* Info Colors */
  --color-info-50: var(--color-info-50);
  --color-info-100: var(--color-info-100);
  --color-info-500: var(--color-info-500);
  --color-info-600: var(--color-info-600);
  --color-info-700: var(--color-info-700);
  --color-info-200: #bfdbfe;
  --color-info-800: #1e40af;
  --color-info-900: #1e3a8a;

  /* Font Families */
  --font-family-sans: var(--font-sans);
  --font-family-serif: var(--font-serif);
  --font-family-mono: var(--font-mono);
  --font-family-display: var(--font-display);

  /* Font Sizes */
  --font-size-xs: var(--font-size-xs);
  --font-size-sm: var(--font-size-sm);
  --font-size-base: var(--font-size-base);
  --font-size-lg: var(--font-size-lg);
  --font-size-xl: var(--font-size-xl);
  --font-size-2xl: var(--font-size-2xl);
  --font-size-3xl: var(--font-size-3xl);
  --font-size-4xl: var(--font-size-4xl);
  --font-size-5xl: var(--font-size-5xl);
  --font-size-6xl: var(--font-size-6xl);
  --font-size-7xl: var(--font-size-7xl);

  /* Spacing - using Tailwind's default spacing scale enhanced with our variables */
  --spacing-0: var(--spacing-0);
  --spacing-px: var(--spacing-px);
  --spacing-0-5: var(--spacing-0-5);
  --spacing-1: var(--spacing-1);
  --spacing-1-5: var(--spacing-1-5);
  --spacing-2: var(--spacing-2);
  --spacing-2-5: var(--spacing-2-5);
  --spacing-3: var(--spacing-3);
  --spacing-3-5: var(--spacing-3-5);
  --spacing-4: var(--spacing-4);
  --spacing-5: var(--spacing-5);
  --spacing-6: var(--spacing-6);
  --spacing-7: var(--spacing-7);
  --spacing-8: var(--spacing-8);
  --spacing-9: var(--spacing-9);
  --spacing-10: var(--spacing-10);
  --spacing-11: var(--spacing-11);
  --spacing-12: var(--spacing-12);
  --spacing-14: var(--spacing-14);
  --spacing-16: var(--spacing-16);
  --spacing-20: var(--spacing-20);
  --spacing-24: var(--spacing-24);
  --spacing-28: var(--spacing-28);
  --spacing-32: var(--spacing-32);
  --spacing-36: var(--spacing-36);
  --spacing-40: var(--spacing-40);
  --spacing-44: var(--spacing-44);
  --spacing-48: var(--spacing-48);
  --spacing-52: var(--spacing-52);
  --spacing-56: var(--spacing-56);
  --spacing-60: var(--spacing-60);
  --spacing-64: var(--spacing-64);
  --spacing-72: var(--spacing-72);
  --spacing-80: var(--spacing-80);
  --spacing-96: var(--spacing-96);

  /* Border Radius */
  --radius-none: var(--radius-none);
  --radius-sm: var(--radius-sm);
  --radius-DEFAULT: var(--radius-base);
  --radius-md: var(--radius-md);
  --radius-lg: var(--radius-lg);
  --radius-xl: var(--radius-xl);
  --radius-2xl: var(--radius-2xl);
  --radius-3xl: var(--radius-3xl);
  --radius-full: var(--radius-full);

  /* Shadows */
  --shadow-xs: var(--shadow-xs);
  --shadow-sm: var(--shadow-sm);
  --shadow-DEFAULT: var(--shadow-base);
  --shadow-md: var(--shadow-md);
  --shadow-lg: var(--shadow-lg);
  --shadow-xl: var(--shadow-xl);
  --shadow-2xl: var(--shadow-2xl);
  --shadow-inner: var(--shadow-inner);
  --shadow-none: var(--shadow-none);
}

/* ============================================
   Global Styles
   ============================================ */

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  font-size: var(--font-size-base);
  line-height: var(--line-height-normal);
  color: var(--color-text-primary);
  background-color: var(--color-background);
  transition: background-color var(--transition-base), color var(--transition-base);
}

/* ============================================
   Utility Classes
   ============================================ */

.text-balance {
  text-wrap: balance;
}

.text-pretty {
  text-wrap: pretty;
}
